291	    const text = serialize()
292	    if (text === null) return
293	    writeSyncAt(mySeq, text)
294	  }
295	
296	  function reportDropped(dropped: number, kept: number): void {
297	    if (dropped <= 0) return
298	    const dest = preserveCopy(fileOf())
299	    console.error(
300	      `[ai] ${label} 파일에서 읽을 수 없는 항목 ${dropped}개를 제외하고 ${kept}개를 복구했습니다.`
301	      + (dest ? ` 원본은 ${path.basename(dest)} 로 보존했습니다.` : ' (원본 보존 실패)'),
302	    )
303	  }
304	
305	  return { markDirty, flush, reportDropped }
306	}
