8	// 에이전트 작업 매크로 — 자주 쓰는 작업 지시를 저장했다가 아무 페이지에서나 한 번에 재실행.
9	// userData/ai-agent-tasks.json 에 저장(원자적 tmp+rename, 디바운스).
10	
11	export interface SavedAgentTask {
12	  id: string
13	  name: string
14	  task: string
15	  createdAt: number
16	  lastRunAt?: number
17	}
18	
19	export const savedTaskEvents = new EventEmitter()
20	
21	const MAX_TASKS = 50
22	let cache: SavedAgentTask[] | null = null
23	let writeTimer: NodeJS.Timeout | null = null
24	let dirty = false
25	let quitHooked = false
26	
27	function filePath(): string {
28	  return path.join(app.getPath('userData'), 'ai-agent-tasks.json')
29	}
30	
31	function isValid(t: unknown): t is SavedAgentTask {
32	  if (!t || typeof t !== 'object') return false
33	  const o = t as Record<string, unknown>
34	  return typeof o.id === 'string' && typeof o.task === 'string'
35	}
36	
37	export function initSavedTasks(): void {
38	  if (!quitHooked) { quitHooked = true; try { app.on('before-quit', flushSavedTasks) } catch { /* ignore */ } }
39	  if (cache !== null) return
40	  try {
41	    if (existsSync(filePath())) {
42	      const raw = JSON.parse(readFileSync(filePath(), 'utf-8')) as { tasks?: unknown }
43	      cache = Array.isArray(raw?.tasks) ? raw.tasks.filter(isValid) : []
44	    } else {
45	      cache = []
46	    }
47	  } catch (err) {
48	    console.warn('[ai] saved tasks load failed', err)
49	    cache = []
50	  }
51	}
52	
53	function all(): SavedAgentTask[] {
54	  if (cache === null) initSavedTasks()
55	  return cache ?? []
56	}
57	
58	function schedulePersist(): void {
59	  dirty = true
60	  if (writeTimer) clearTimeout(writeTimer)
61	  writeTimer = setTimeout(() => { void persist() }, 300)
62	}
63	
64	async function persist(): Promise<void> {
65	  try {
66	    await mkdir(path.dirname(filePath()), { recursive: true })
67	    const tmp = filePath() + '.tmp'
68	    await writeFile(tmp, JSON.stringify({ version: 1, tasks: all() }), 'utf-8')
69	    await rename(tmp, filePath())
70	    dirty = false
71	  } catch (err) {
72	    console.warn('[ai] saved tasks persist failed', err)
73	  }
74	}
75	
76	export function flushSavedTasks(): void {
77	  if (writeTimer) { clearTimeout(writeTimer); writeTimer = null }
78	  if (!dirty) return
79	  try {
80	    mkdirSync(path.dirname(filePath()), { recursive: true })
81	    const tmp = filePath() + '.tmp' // 원자적 쓰기 — 종료 중 크래시로 파일이 잘리지 않도록
82	    writeFileSync(tmp, JSON.stringify({ version: 1, tasks: all() }), 'utf-8')
83	    renameSync(tmp, filePath())
84	    dirty = false
85	  } catch (err) {
86	    console.warn('[ai] saved tasks flush failed', err)
87	  }
88	}
89	
90	function emitChanged(): void {
91	  savedTaskEvents.emit('changed', listSavedTasks())
92	}
93	
94	export function listSavedTasks(): SavedAgentTask[] {
95	  return all().slice().sort((a, b) => b.createdAt - a.createdAt)
96	}
97	
98	function deriveName(task: string): string {
99	  const t = task.replace(/\s+/g, ' ').trim()
100	  if (!t) return '작업'
101	  return t.length > 30 ? t.slice(0, 30) + '…' : t
102	}
103	
104	export function addSavedTask(task: string, name?: string): SavedAgentTask | null {
105	  const t = String(task ?? '').trim()
106	  if (!t) return null
107	  const item: SavedAgentTask = {
108	    id: randomUUID(),
109	    name: name && name.trim() ? name.trim().slice(0, 60) : deriveName(t),
110	    task: t,
111	    createdAt: Date.now(),
112	  }
113	  const list = all()
114	  list.unshift(item)
115	  if (list.length > MAX_TASKS) cache = list.slice(0, MAX_TASKS)
116	  schedulePersist()
117	  emitChanged()
118	  return item
119	}
120	
121	export function removeSavedTask(id: string): void {
122	  const list = all()
123	  const idx = list.findIndex((t) => t.id === id)
124	  if (idx < 0) return
125	  list.splice(idx, 1)
126	  schedulePersist()
127	  emitChanged()
128	}
129	
130	export function renameSavedTask(id: string, name: string): void {
131	  const t = all().find((x) => x.id === id)
132	  if (!t) return
133	  t.name = String(name ?? '').replace(/\s+/g, ' ').trim().slice(0, 60) || t.name
134	  schedulePersist()
135	  emitChanged()
136	}
137	
138	export function touchSavedTask(id: string): void {
139	  const t = all().find((x) => x.id === id)
140	  if (!t) return
141	  t.lastRunAt = Date.now()
142	  schedulePersist()
143	  emitChanged()
144	}
