169	export interface JsonStore {
170	  /** 상태가 바뀌었다 — 디바운스 저장 예약. */
171	  markDirty(): void
172	  /** 종료 시 동기 저장. 저장할 변경이 없으면 **파일을 건드리지 않는다**. */
173	  flush(): void
174	  /** 부분 손상으로 항목을 버렸을 때 — 원본을 복사본으로 보존하고 몇 개를 버렸는지 알린다. */
175	  reportDropped(dropped: number, kept: number): void
176	}
177	
178	export function createJsonStore(opts: {
179	  /** userData 아래 파일 이름 (예: 'ai-chats.json') */
180	  fileName: string
181	  /** 로그에 쓰는 한국어 이름 (예: '대화') */
182	  label: string
183	  debounceMs: number
184	  /** 지금 디스크에 쓸 객체 — 호출 시점의 최신 상태여야 한다. */
185	  snapshot: () => unknown
186	}): JsonStore {
187	  const { fileName, label, debounceMs, snapshot } = opts
188	
189	  let seq = 0             // 변경마다 증가
190	  let persistedSeq = 0    // 디스크에 마지막으로 **착지한** 스냅샷의 seq
191	  let timer: NodeJS.Timeout | null = null
192	  let firstDirtyAt = 0
193	  let writing = false
194	  let tmpCounter = 0
195	
196	  const fileOf = (): string => userDataFile(fileName)
197	  const tmpOf = (file: string): string => `${file}.${process.pid}-${++tmpCounter}.tmp`
198	
199	  function serialize(): string | null {
200	    try {
201	      return JSON.stringify(snapshot())
202	    } catch (err) {
203	      console.warn(`[ai] ${label} 직렬화 실패`, err)
204	      return null
205	    }
206	  }
207	
208	  function scheduleTimer(): void {
209	    if (timer) return
210	    firstDirtyAt = firstDirtyAt || Date.now()
211	    timer = setTimeout(() => { timer = null; firstDirtyAt = 0; void runPersist() }, debounceMs)
212	  }
213	
214	  function markDirty(): void {
215	    seq++
216	    if (timer) {
217	      // 변경이 쉼 없이 들어와도 저장이 굶지 않도록, 첫 변경 이후 일정 시간이 지나면 타이머를 더 미루지 않는다.
218	      if (Date.now() - firstDirtyAt >= MAX_SAVE_DELAY_MS) return
219	      clearTimeout(timer)
220	      timer = null
221	    }
222	    scheduleTimer()
223	  }
224	
225	  /** 동기 원자적 쓰기. 성공하면 `persistedSeq` 를 올린다. */
226	  function writeSyncAt(mySeq: number, text: string): boolean {
227	    const file = fileOf()
228	    let tmp = ''
229	    try {
230	      mkdirSync(path.dirname(file), { recursive: true })
231	      tmp = tmpOf(file)
232	      writeFileSync(tmp, text, 'utf-8')
233	      renameSync(tmp, file)
234	      persistedSeq = Math.max(persistedSeq, mySeq)
235	      return true
236	    } catch (err) {
237	      if (tmp) { try { unlinkSync(tmp) } catch { /* ignore */ } }
238	      console.warn(`[ai] ${label} 저장 실패(동기)`, err)
239	      return false
240	    }
241	  }
242	
243	  async function runPersist(): Promise<void> {
244	    if (writing) return  // single-flight — 진행 중인 루프가 최신 seq 까지 따라간다
245	    writing = true
246	    try {
247	      // 직렬화 이후 들어온 변경까지 따라가도록 반복한다(무한 루프 방지용 상한).
248	      for (let guard = 0; guard < 50; guard++) {
249	        if (seq <= persistedSeq) break
250	        const mySeq = seq
251	        const text = serialize()
252	        if (text === null) break
253	        const file = fileOf()
254	        let tmp = ''
255	        try {
256	          await mkdir(path.dirname(file), { recursive: true })
257	          tmp = tmpOf(file)
258	          await writeFile(tmp, text, 'utf-8')
259	          if (persistedSeq >= mySeq) {
260	            // 내가 쓰는 동안 더 새(또는 같은) 스냅샷이 이미 착지했다 → 내 것을 착지시키면 되돌리기다.
261	            await unlink(tmp).catch(() => {})
262	            continue
263	          }
264	          await rename(tmp, file)
265	          if (persistedSeq > mySeq) {
266	            // rename 도중 동기 flush 가 더 새 스냅샷을 착지시켰다 → 방금 그걸 덮었다. 즉시 동기 복구.
267	            const cur = seq
268	            const fresh = serialize()
269	            if (fresh !== null) writeSyncAt(cur, fresh)
270	          } else {
271	            persistedSeq = mySeq
272	          }
273	        } catch (err) {
274	          if (tmp) { await unlink(tmp).catch(() => {}) }
275	          // persistedSeq 를 올리지 않는다 → 다음 변경이나 종료 flush 에서 다시 시도된다.
276	          console.warn(`[ai] ${label} 저장 실패`, err)
277	          break
278	        }
279	      }
280	    } finally {
281	      writing = false
282	    }
283	    // 루프가 도는 동안 들어온 변경(또는 실패로 남은 변경)이 있으면 다시 예약한다.
284	    if (seq > persistedSeq) scheduleTimer()
285	  }
286	
287	  function flush(): void {
288	    if (timer) { clearTimeout(timer); timer = null; firstDirtyAt = 0 }
289	    if (seq <= persistedSeq) return  // 저장할 변경 없음 — 정상 파일을 건드리지 않는다
290	    const mySeq = seq
291	    const text = serialize()
292	    if (text === null) return
293	    writeSyncAt(mySeq, text)
294	  }
295	
296	  function reportDropped(dropped: number, kept: number): void {
297	    if (dropped <= 0) return
298	    const dest = preserveCopy(fileOf())
299	    console.error(
300	      `[ai] ${label} 파일에서 읽을 수 없는 항목 ${dropped}개를 제외하고 ${kept}개를 복구했습니다.`
301	      + (dest ? ` 원본은 ${path.basename(dest)} 로 보존했습니다.` : ' (원본 보존 실패)'),
302	    )
303	  }
304	
305	  return { markDirty, flush, reportDropped }
306	}
