function priorContextBlock(turns: AgentTurn[] | undefined): string {
  if (!turns || turns.length === 0) return ''
  const lines = turns.map((t, i) => `${i + 1}. 이전 지시: ${t.task}\n   → 결과: ${t.outcome}`).join('\n')
  return '\n\n# 지금까지의 대화 맥락 (같은 세션의 이전 지시와 결과)\n'
