// 임시 자체 검증 스크립트 — probeImage 를 손으로 조립한 최소 바이트로 시험한다. 검증 후 삭제할 것.
const { execSync } = require('node:child_process');

// TS 를 그대로 요구하면 빠르므로, 컴파일된 산출물을 사용.
// app/dist/main/features/ai/artifacts.js 가 이미 있으면 그걸 쓰고, 없으면 최소 재구현으로 로직만 검증.
let mod;
try {
  mod = require('./app/dist/main/features/ai/artifacts.js');
} catch (e) {
  console.error('컴파일된 산출물이 없습니다 — npm run build:main 먼저 실행하거나 ts-node 필요:', e.message);
  process.exit(1);
}

const { probeImage } = mod;

let pass = 0, fail = 0;
function check(name, buf, expectOk, expectFmt, expectW, expectH) {
  const r = probeImage(buf);
  const ok = r.ok === expectOk &&
    (expectOk ? (r.format === expectFmt && r.width === expectW && r.height === expectH) : true);
  if (ok) { pass++; console.log(`PASS ${name}: ${JSON.stringify(r)}`); }
  else { fail++; console.log(`FAIL ${name}: got ${JSON.stringify(r)} expected ok=${expectOk} fmt=${expectFmt} w=${expectW} h=${expectH}`); }
}

// ---- PNG: 8바이트 시그니처 + IHDR 청크(길이4 + 'IHDR' + width4 + height4 + ...) ----
function buildPng(w, h) {
  const sig = Buffer.from([0x89,0x50,0x4e,0x47,0x0d,0x0a,0x1a,0x0a]);
  const lenBuf = Buffer.alloc(4); lenBuf.writeUInt32BE(13, 0); // IHDR 데이터 길이 13
  const typeBuf = Buffer.from('IHDR', 'ascii');
  const wBuf = Buffer.alloc(4); wBuf.writeUInt32BE(w, 0);
  const hBuf = Buffer.alloc(4); hBuf.writeUInt32BE(h, 0);
  const rest = Buffer.from([8,6,0,0,0]); // bit depth, color type, compression, filter, interlace
  const crc = Buffer.alloc(4);
  return Buffer.concat([sig, lenBuf, typeBuf, wBuf, hBuf, rest, crc]);
}
check('PNG 1920x1080', buildPng(1920, 1080), true, 'png', 1920, 1080);

// ---- JPEG: FFD8FF + APP0(FFE0) 세그먼트(무시) + SOF0(FFC0) 세그먼트(치수 포함) ----
function buildJpeg(w, h) {
  const soi = Buffer.from([0xff, 0xd8]);
  // APP0 세그먼트: FF E0, len(2)=16, 'JFIF\0' + 나머지 패딩
  const app0Payload = Buffer.concat([Buffer.from('JFIF\0', 'ascii'), Buffer.alloc(9)]);
  const app0Len = Buffer.alloc(2); app0Len.writeUInt16BE(app0Payload.length + 2, 0);
  const app0 = Buffer.concat([Buffer.from([0xff, 0xe0]), app0Len, app0Payload]);
  // SOF0: FF C0, len(2)=8(=2+1+2+2+1), precision(1)=8, height(2), width(2), numComponents(1)=1
  const sofPayload = Buffer.alloc(6);
  sofPayload.writeUInt8(8, 0);
  sofPayload.writeUInt16BE(h, 1);
  sofPayload.writeUInt16BE(w, 3);
  sofPayload.writeUInt8(1, 5);
  const sofLen = Buffer.alloc(2); sofLen.writeUInt16BE(sofPayload.length + 2, 0);
  const sof0 = Buffer.concat([Buffer.from([0xff, 0xc0]), sofLen, sofPayload]);
  return Buffer.concat([soi, app0, sof0]);
}
check('JPEG 800x600', buildJpeg(800, 600), true, 'jpeg', 800, 600);

// ---- WebP VP8X (extended, 치수 = value+1) ----
function buildWebpVp8x(w, h) {
  const riff = Buffer.from('RIFF', 'ascii');
  const webp = Buffer.from('WEBP', 'ascii');
  const fourcc = Buffer.from('VP8X', 'ascii');
  const chunkSize = Buffer.alloc(4); chunkSize.writeUInt32LE(10, 0);
  const flags = Buffer.from([0x10]);
  const reserved = Buffer.alloc(3);
  const wMinus1 = w - 1, hMinus1 = h - 1;
  const wBuf = Buffer.from([wMinus1 & 0xff, (wMinus1 >> 8) & 0xff, (wMinus1 >> 16) & 0xff]);
  const hBuf = Buffer.from([hMinus1 & 0xff, (hMinus1 >> 8) & 0xff, (hMinus1 >> 16) & 0xff]);
  const riffLen = Buffer.alloc(4); riffLen.writeUInt32LE(4 + 8 + 10, 0);
  return Buffer.concat([riff, riffLen, webp, fourcc, chunkSize, flags, reserved, wBuf, hBuf]);
}
check('WebP VP8X 400x300', buildWebpVp8x(400, 300), true, 'webp', 400, 300);

// ---- GIF ----
function buildGif(w, h) {
  const sig = Buffer.from('GIF89a', 'ascii');
  const wBuf = Buffer.alloc(2); wBuf.writeUInt16LE(w, 0);
  const hBuf = Buffer.alloc(2); hBuf.writeUInt16LE(h, 0);
  return Buffer.concat([sig, wBuf, hBuf, Buffer.alloc(3)]);
}
check('GIF 100x50', buildGif(100, 50), true, 'gif', 100, 50);

// ---- 실패 케이스들 ----
check('빈 버퍼', Buffer.alloc(0), false);
check('HTML 문서', Buffer.from('<!DOCTYPE html><html><body>login</body></html>', 'utf-8'), false);
check('HTML 대문자 무관+공백', Buffer.from('   \n<HTML><body>x</body></html>', 'utf-8'), false);
check('잘린 PNG(3바이트)', Buffer.from([0x89, 0x50, 0x4e]), false);
check('확장자만 png인 텍스트', Buffer.from('this is not an image, just text pretending .png', 'utf-8'), false);
check('알수없는 바이너리', Buffer.from([0x01,0x02,0x03,0x04,0x05,0x06,0x07,0x08]), false);
check('PNG 시그니처만 있고 IHDR 없음(짧음)', Buffer.from([0x89,0x50,0x4e,0x47,0x0d,0x0a,0x1a,0x0a,0,0,0,0]), false);

console.log(`\n총 ${pass + fail}건 시험 — PASS ${pass} / FAIL ${fail}`);
process.exit(fail > 0 ? 1 : 0);

