// 임시 자체 검증 스크립트 — 실행 후 삭제한다.
const path = require('path')
const os = require('os')
const fs = require('fs')
const Module = require('module')

// electron 모듈을 흉내낸다 (app.getPath('userData') 만 있으면 json-store.ts 가 동작한다)
const fakeUserData = fs.mkdtempSync(path.join(os.tmpdir(), 'blog-engage-verify-'))
const fakeElectron = {
  app: {
    getPath: (name) => { if (name === 'userData') return fakeUserData; return os.tmpdir() },
    on: () => {},
    isPackaged: false,
  },
}
const origResolve = Module._resolveFilename
Module._resolveFilename = function (request, ...rest) {
  if (request === 'electron') return 'electron'
  return origResolve.call(this, request, ...rest)
}
const origLoad = Module._load
Module._load = function (request, ...rest) {
  if (request === 'electron') return fakeElectron
  return origLoad.call(this, request, ...rest)
}

const mod = require(path.join(os.tmpdir(), 'blog-engage-test-bundle.cjs'))

let failures = 0
function check(name, cond) {
  if (cond) { console.log(`OK   ${name}`) } else { console.log(`FAIL ${name}`); failures++ }
}

// 1. normalizeTargetUrl 이 같은 키로 만드는 쌍
const a1 = mod.normalizeTargetUrl('http://www.a.com/p/1?utm_source=x')
const a2 = mod.normalizeTargetUrl('https://a.com/p/1')
check(`1a) ${a1} === ${a2}`, a1 === a2)

const b1 = mod.normalizeTargetUrl('https://a.com/p/1#c')
const b2 = mod.normalizeTargetUrl('https://a.com/p/1/')
check(`1b) ${b1} === ${b2}`, b1 === b2)

// 2. 다른 키여야 하는 쌍
const c1 = mod.normalizeTargetUrl('https://a.com/p?id=1')
const c2 = mod.normalizeTargetUrl('https://a.com/p?id=2')
check(`2) ${c1} !== ${c2}`, c1 !== c2)

// 3. alreadyDid: 기록 전 false -> 기록 후 true -> 다른 계정은 false
mod.initEngageLedger()
const key3 = mod.normalizeTargetUrl('https://example.com/post/123')
check('3a) 기록 전 false', mod.alreadyDid(key3, 'acct1', 'comment') === false)
mod.recordEngagement({ key: key3, account: 'acct1', action: 'comment', note: '좋은 인사이트네요' })
check('3b) 기록 후 true', mod.alreadyDid(key3, 'acct1', 'comment') === true)
check('3c) 다른 계정은 여전히 false', mod.alreadyDid(key3, 'acct2', 'comment') === false)
check('3d) 같은 계정 다른 action(like)은 false', mod.alreadyDid(key3, 'acct1', 'like') === false)

// 중복 기록 무시 확인 (최초 기록 보존)
const before = mod.listEngagements().find((e) => e.key === key3 && e.account === 'acct1' && e.action === 'comment')
mod.recordEngagement({ key: key3, account: 'acct1', action: 'comment', note: '다른 노트로 덮어쓰기 시도' })
const after = mod.listEngagements().find((e) => e.key === key3 && e.account === 'acct1' && e.action === 'comment')
check('3e) 중복 기록은 무시되어 최초 노트 보존', before.note === after.note && before.at === after.at)

// 빈 계정 정규화 확인 ('' 와 'default' 가 같은 계정으로 취급)
mod.recordEngagement({ key: 'https://x.com/z', account: '', action: 'like' })
check('3f) 빈 계정은 default 로 정규화', mod.alreadyDid('https://x.com/z', 'default', 'like') === true)

// 4. draft 모드에는 발행금지 표식이 있고, act 모드에는 없다
