const actTask = mod.buildBlogEngageTask({ topic: 'test', maxPosts: 3, actions: ['comment', 'like'], mode: 'act' })
check('4a) draft 에 [모드: 발행 금지] 포함', draftTask.task.includes('[모드: 발행 금지]'))
check('4b) act 에는 [모드: 발행 금지] 없음', !actTask.task.includes('[모드: 발행 금지]'))

// 5. maxPosts 999 -> 20 으로 clamp
const clamped = mod.buildBlogEngageTask({ topic: 'test', maxPosts: 999, actions: ['comment'], mode: 'draft' })
check('5) maxPosts=999 -> 20 으로 clamp (문구에 20 포함)', clamped.task.includes('최대 20개'))

// 부가: allowedHosts 가 비어있지 않은지
check('부가) allowedHosts 비어있지 않음', draftTask.allowedHosts.length > 0)

// 부가: myBlogUrl 없이도 topic 만으로 동작
const noBlogTask = mod.buildBlogEngageTask({ maxPosts: 2, actions: ['comment'], mode: 'draft', topic: '요리' })
check('부가) myBlogUrl 없이 topic 만으로 openUrl 생성', noBlogTask.openUrl.includes(encodeURIComponent('요리')))

console.log('')
