// ---- WebP VP8 (simple lossy, 14비트 폭·높이) ----
function buildWebpVp8(w, h) {
  const riff = Buffer.from('RIFF', 'ascii');
  const webp = Buffer.from('WEBP', 'ascii');
  const fourcc = Buffer.from('VP8 ', 'ascii');
  const payload = Buffer.alloc(10); // frame tag(3) + start code(3) + width(2) + height(2)
  payload[3] = 0x9d; payload[4] = 0x01; payload[5] = 0x2a; // VP8 키프레임 시작 코드
  payload.writeUInt16LE(w & 0x3fff, 6);
  payload.writeUInt16LE(h & 0x3fff, 8);
  const chunkSize = Buffer.alloc(4); chunkSize.writeUInt32LE(payload.length, 0);
  const riffLen = Buffer.alloc(4); riffLen.writeUInt32LE(4 + 8 + payload.length, 0);
  return Buffer.concat([riff, riffLen, webp, fourcc, chunkSize, payload]);
}
check('WebP VP8(simple) 640x480', buildWebpVp8(640, 480), true, 'webp', 640, 480);

// ---- WebP VP8L (lossless, bits: width-1(14비트)+height-1(14비트)+...) ----
function buildWebpVp8l(w, h) {
  const riff = Buffer.from('RIFF', 'ascii');
  const webp = Buffer.from('WEBP', 'ascii');
  const fourcc = Buffer.from('VP8L', 'ascii');
  const bits = ((w - 1) & 0x3fff) | (((h - 1) & 0x3fff) << 14);
  const payload = Buffer.alloc(5);
  payload[0] = 0x2f; // VP8L 시그니처 바이트
  payload.writeUInt32LE(bits >>> 0, 1);
  const chunkSize = Buffer.alloc(4); chunkSize.writeUInt32LE(payload.length, 0);
  const riffLen = Buffer.alloc(4); riffLen.writeUInt32LE(4 + 8 + payload.length, 0);
  return Buffer.concat([riff, riffLen, webp, fourcc, chunkSize, payload]);
}
check('WebP VP8L 300x200', buildWebpVp8l(300, 200), true, 'webp', 300, 200);

// ---- GIF ----

check('PNG 시그니처만 있고 IHDR 없음(짧음)', Buffer.from([0x89,0x50,0x4e,0x47,0x0d,0x0a,0x1a,0x0a,0,0,0,0]), false);
check('PNG 치수 0x0(손상)', buildPng(0, 0), false);
check('GIF 헤더만 있고 치수 필드 없음(짧음)', Buffer.from('GIF89a', 'ascii'), false);
check('WebP RIFF/WEBP 는 맞지만 fourcc 미지원', Buffer.concat([Buffer.from('RIFF'), Buffer.alloc(4), Buffer.from('WEBP'), Buffer.from('ANIM'), Buffer.alloc(10)]), false);

