import { startSocialFixtures } from './build/social-fixture-server.mjs'
import crypto from 'node:crypto'

const fx = await startSocialFixtures()
console.log('base:', fx.base, 'altBase:', fx.altBase)

let allOk = true
function check(name, cond, detail) {
  console.log((cond ? 'OK  ' : 'FAIL') + ' - ' + name + (detail ? ' (' + detail + ')' : ''))
  if (!cond) allOk = false
}

// 1) generated-1.png 가 진짜 PNG 인지 (시그니처 + IHDR 치수 800x600)
const r1 = await fetch(fx.base + '/img/generated-1.png')
const buf1 = Buffer.from(await r1.arrayBuffer())
const sigOk = buf1.subarray(0, 8).equals(Buffer.from([0x89,0x50,0x4e,0x47,0x0d,0x0a,0x1a,0x0a]))
const w1 = buf1.readUInt32BE(16)
const h1 = buf1.readUInt32BE(20)
check('1) generated-1.png PNG 시그니처', sigOk)
check('1) generated-1.png IHDR 800x600', w1 === 800 && h1 === 600, `실제 ${w1}x${h1}`)

// 2) generated-1 vs generated-2 sha256 다른지
const r2 = await fetch(fx.base + '/img/generated-2.png')
const buf2 = Buffer.from(await r2.arrayBuffer())
const sha1 = crypto.createHash('sha256').update(buf1).digest('hex')
const sha2 = crypto.createHash('sha256').update(buf2).digest('hex')
check('2) generated-1 vs generated-2 sha256 다름', sha1 !== sha2, `${sha1.slice(0,8)} vs ${sha2.slice(0,8)}`)

// 3) fake.png 본문이 HTML 인지
const r3 = await fetch(fx.base + '/img/fake.png')
const ct3 = r3.headers.get('content-type')
const text3 = await r3.text()
check('3) fake.png Content-Type=image/png', /image\/png/.test(ct3 || ''), ct3)
check('3) fake.png 본문이 HTML', /<html/i.test(text3))

// 4) needcookie.png 쿠키 없으면 403, 쿠키 있으면 PNG
const r4a = await fetch(fx.base + '/img/needcookie.png')
check('4) needcookie 쿠키없음 403', r4a.status === 403, `status=${r4a.status}`)
const r4set = await fetch(fx.base + '/setcookie')
const setCookieHeader = r4set.headers.get('set-cookie')
check('4) /setcookie 가 Set-Cookie 반환', !!setCookieHeader && setCookieHeader.includes('sess=ok'), setCookieHeader)
const r4b = await fetch(fx.base + '/img/needcookie.png', { headers: { Cookie: 'sess=ok' } })
const buf4b = Buffer.from(await r4b.arrayBuffer())
const sig4bOk = buf4b.subarray(0, 8).equals(Buffer.from([0x89,0x50,0x4e,0x47,0x0d,0x0a,0x1a,0x0a]))
check('4) needcookie 쿠키있음 200+PNG', r4b.status === 200 && sig4bOk, `status=${r4b.status}`)

// 5) /blog/post/1 본문 600자 이상 + 고유 표지
const r5 = await fetch(fx.base + '/blog/post/1')
const html5 = await r5.text()
const textOnly5 = html5.replace(/<[^>]+>/g, '')
check('5) blog/post/1 텍스트 600자 이상', textOnly5.length >= 600, `길이=${textOnly5.length}`)
check('5) blog/post/1 고유 표지 포함', html5.includes('POST-1-MARKER'))

// 추가: SNS 업로드 왕복 검증 (파일 바이트가 그대로 도착하는지)
const fileBytes = Buffer.from('테스트 이미지 바이트 - 임의 데이터 0123456789')
const form = new FormData()
form.append('file', new Blob([fileBytes], { type: 'image/png' }), 'test.png')
form.append('caption', '테스트 캡션')
const rPub = await fetch(fx.base + '/sns/publish', { method: 'POST', body: form })
const pubJson = await rPub.json()
const expectedSha = crypto.createHash('sha256').update(fileBytes).digest('hex')
const stateResp = await fetch(fx.base + '/state')
const stateJson = await stateResp.json()
const rec = stateJson.publishes.find(p => p.id === pubJson.id)
check('추가) SNS 업로드 sha256 일치', !!rec && rec.sha256 === expectedSha, JSON.stringify(rec))
check('추가) SNS 업로드 caption 보존', !!rec && rec.caption === '테스트 캡션')

// 추가: cross-origin iframe embed 라우트 확인
const rEmbed = await fetch(fx.altBase + '/sns/embed')
check('추가) altBase /sns/embed 200', rEmbed.status === 200)

// 추가: blog/post/9 500 실패
const r9 = await fetch(fx.base + '/blog/post/9')
check('추가) blog/post/9 500', r9.status === 500)

// 추가: blog/post/3 사전 좋아요 상태
const rState2 = await fetch(fx.base + '/state')
const stateJson2 = await rState2.json()
const like3 = stateJson2.likes.find(l => l.key === 'post:3')
check('추가) post:3 사전 좋아요=true', !!like3 && like3.liked === true, JSON.stringify(like3))

// 6) close() 가 3초 안에 끝나는지
const t0 = Date.now()
await fx.close()
const closeMs = Date.now() - t0
check('6) close() 3초 이내', closeMs < 3000, `${closeMs}ms`)

console.log('---')
console.log(allOk ? 'ALL_CHECKS_PASSED' : 'SOME_CHECKS_FAILED')
process.exit(allOk ? 0 : 1)
EOF

