export interface AgentEvent { type: string; [k: string]: unknown }
type Emit = (evt: AgentEvent) => void

const DEFAULT_MAX_STEPS = 25
const STUCK_REPEAT = 3    // 같은 동작이 이만큼 반복되면 막힘으로 보고 사용자에게 물음
