45	import { getFreePorts } from './lib/ports.mjs'
46	
47	// ───────────────────────── 공통 HTML/HTTP 헬퍼 ─────────────────────────
48	
49	function escapeHtml(s) {
50	  return String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]))
51	}
52	
53	function page(body, title = 'social-fixture') {
54	  return `<!doctype html><html><head><meta charset="utf-8"><title>${escapeHtml(title)}</title></head><body>${body}</body></html>`
55	}
56	
57	function sendHtml(res, status, body) {
58	  const buf = Buffer.from(body, 'utf8')
59	  res.writeHead(status, {
60	    'Content-Type': 'text/html; charset=utf-8',
61	    'Content-Length': String(buf.length),
62	    'Cache-Control': 'no-store',
63	  })
64	  res.end(buf)
